#!/usr/bin/env python3
"""Modern Climate Data Analysis Script - Python 3."""

from pathlib import Path
from configparser import ConfigParser

import numpy as np
import pandas as pd

BASE_DIR = Path(__file__).resolve().parent


def load_config(path: Path) -> ConfigParser:
    config = ConfigParser()
    config.read(path, encoding="utf-8")
    return config


def load_temperature_data(path: Path) -> pd.DataFrame:
    df = pd.read_csv(path, parse_dates=["date"], encoding="utf-8")
    return df


def calculate_mean_temperature(df: pd.DataFrame) -> pd.Series:
    return df.groupby("station_id")["temperature"].mean()


def main() -> None:
    config = load_config(BASE_DIR / "climate_analyzer" / "config.ini")
    data_path = BASE_DIR / "climate_analyzer" / "sample_data" / "climate_data.csv"

    df = load_temperature_data(data_path)
    means = calculate_mean_temperature(df)

    for station_id, mean_temp in means.items():
        print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


if __name__ == "__main__":
    main()

